 $('#document-canvas').addEventListener('click',event=>{const action=event.target.closest('[data-block-action]'),add=event.target.closest('[data-add-block]');const video=event.target.closest('[data-edit-video]');if(video)showVideo(Number(video.dataset.editVideo));const clickedBlock=event.target.closest('[data-block-index]');if(clickedBlock)activate(Number(clickedBlock.dataset.blockIndex));if(event.target.closest('[data-edit-cover]')&&!event.target.closest('.hero-grip'))showMedia('cover');if(add){active=p.blocks.length-1;add.dataset.addBlock==='image'?showMedia():add.dataset.addBlock==='youtube'?showVideo():insert(add.dataset.addBlock);}if(action&&!busy){if(action.dataset.blockAction==='photo'){activate(Number(action.dataset.index));$('#image-dialog').showModal();return;}syncDocument();const index=Number(action.dataset.index),to=action.dataset.blockAction==='up'?index-1:index+1;if(action.dataset.blockAction==='full'){let first=index,last=index;while(first>0&&p.blocks[first-1].layout==='half')first--;while(last+1<p.blocks.length&&p.blocks[last+1].layout==='half')last++;for(let i=first;i<=last;i++)p.blocks[i].layout='full';}else if(action.dataset.blockAction==='remove')p.blocks.splice(index,1);else if(to>=0&&to<p.blocks.length)[p.blocks[index],p.blocks[to]]=[p.blocks[to],p.blocks[index]];active=Math.min(p.blocks.length-1,Math.max(0,to));paint();changed();}});
 $('#document-canvas').addEventListener('input',event=>{syncDocument();const index=event.target.closest('[data-edit-block]')?.dataset.editBlock;if(index!==undefined){const block=p.blocks[Number(index)];if(block.type==='paragraph'&&/^##\s+/.test(block.text)){block.type='heading';block.text=block.text.replace(/^##\s+/,'');block.runs=[{text:block.text,font:'inherit'}];active=Number(index);paint();const editable=$('[data-edit-block="'+index+'"]');editable.focus();const range=document.createRange();range.selectNodeContents(editable);range.collapse(false);getSelection().removeAllRanges();getSelection().addRange(range);}}changed();});
  document.addEventListener('selectionchange',captureSelection);$$('[data-inline-font]').forEach(button=>{button.addEventListener('pointerdown',event=>event.preventDefault());button.addEventListener('click',()=>applyInlineFont(button.dataset.inlineFont));});
 $('#final-preview').addEventListener('click',()=>{if(!p||busy)return;syncDocument();readSettings();previewSnapshot={type:'nemo-draft-preview',post:structuredClone(p),postType:current.type,pool:pool()};$('#preview-dialog').showModal();$('#preview-frame').contentWindow.postMessage(previewSnapshot,location.origin);});
 addEventListener('message',event=>{if(event.origin===location.origin&&event.source===$('#preview-frame').contentWindow&&event.data?.type==='nemo-preview-ready'&&previewSnapshot)$('#preview-frame').contentWindow.postMessage(previewSnapshot,location.origin);});
 $('#close-final-preview').addEventListener('click',()=>$('#preview-dialog').close());$('#preview-mobile').addEventListener('click',()=>{ $('#preview-dialog').classList.add('preview-mobile');$('#preview-mobile').setAttribute('aria-pressed','true');$('#preview-desktop').setAttribute('aria-pressed','false');});$('#preview-desktop').addEventListener('click',()=>{ $('#preview-dialog').classList.remove('preview-mobile');$('#preview-mobile').setAttribute('aria-pressed','false');$('#preview-desktop').setAttribute('aria-pressed','true');});
 function settingsInput(event){if(!event.target.matches('input,select,textarea')||event.target.id==='related-search')return;syncDocument();if(event.target.matches('[data-related]')){const id=event.target.value;if(event.target.checked){if(p.related.length>=6){event.target.checked=false;toast('관련 글은 최대 6개까지 선택해주세요.');return;}if(!p.related.includes(id))p.related.push(id);}else p.related=p.related.filter(x=>x!==id);renderRelated();}readSettings();paint();changed();}
 $('.editor-settings').addEventListener('input',settingsInput);$('#image-dialog').addEventListener('input',settingsInput);
 $('#media-library').addEventListener('click',event=>{const button=event.target.closest('[data-pick-media]');if(button&&!busy)choosePhoto(library[Number(button.dataset.pickMedia)]);});$('#close-media').addEventListener('click',()=>{if(!busy)$('#media-dialog').close();});$('#media-dialog').addEventListener('cancel',event=>{if(busy)event.preventDefault();});
 $('#photo-upload').addEventListener('change',async event=>{if(busy)return;const files=[...event.target.files];if(new Set([p.visual,...p.blocks.filter(b=>b.type==='image').map(b=>b.src)].filter(Boolean)).size+files.length>24){$('#media-error').textContent='사진은 최대 24장입니다.';event.target.value='';return;}busy=true;event.target.disabled=true;$('#media-error').textContent='업로드 중입니다.';const uploaded=[];try{for(const file of files){if(file.size>12*1024*1024)throw new Error('사진은 한 장당 12MB 이하로 올려주세요.');const buffer=await file.arrayBuffer(),bytes=new Uint8Array(buffer);const mime=bytes[0]===255&&bytes[1]===216&&bytes[2]===255?'image/jpeg':bytes[0]===137&&bytes[1]===80&&bytes[2]===78&&bytes[3]===71?'image/png':String.fromCharCode(...bytes.slice(0,4))==='RIFF'&&String.fromCharCode(...bytes.slice(8,12))==='WEBP'?'image/webp':file.type;const data=await api('/api/admin/media',{method:'POST',headers:{'Content-Type':mime},body:buffer});library.push(data.url);uploaded.push(data.url);}busy=false;if(mediaMode==='cover'&&uploaded[0])choosePhoto(uploaded[0]);else for(const key of uploaded){insert('image',key);if(!p.visual)p.visual=key;}paint();$('#media-dialog').close();}catch(error){$('#media-error').textContent=error.message;if(uploaded.length){busy=false;for(const key of uploaded)insert('image',key);}}finally{busy=false;event.target.disabled=false;event.target.value='';}});
 $('#account-form').addEventListener('submit',async event=>{event.preventDefault();const button=event.currentTarget.querySelector('button');button.disabled=true;$('#account-error').textContent='';try{await api('/api/admin/accounts',{method:'POST',body:JSON.stringify({username:$('#new-username').value,password:$('#new-password').value})});$('#new-password').value='';$('#new-username').value='';await renderAccounts();toast('관리자를 추가했습니다.');}catch(error){$('#account-error').textContent=error.message;}finally{button.disabled=false;}});
 $('#accounts-list').addEventListener('click',async event=>{const button=event.target.closest('[data-account]');if(!button)return;if(button.dataset.action==='revoke'&&!confirm('이 관리자의 권한을 회수하고 현재 로그인을 종료할까요?'))return;button.disabled=true;try{await api('/api/admin/accounts',{method:'POST',body:JSON.stringify({id:button.dataset.account,action:button.dataset.action})});await renderAccounts();}catch(error){toast(error.message);button.disabled=false;}});

 // Settings precede the document, keeping the writing sequence explicit.
 const settings=$('.editor-settings');$('.composer-tools').after(settings);settings.classList.add('settings-collapsed');settings.querySelectorAll(':scope > section').forEach(section=>{const h=section.querySelector('h2'),details=document.createElement('details'),summary=document.createElement('summary');summary.textContent=h.textContent;if(section.classList.contains('post-settings-main'))details.open=true;h.remove();section.parentNode.insertBefore(details,section);details.append(summary,section);});
 function renderRelated(){const q=$('#related-search').value.trim().toLowerCase(),items=pool().filter(x=>x.id!==p.id&&[x.title,x.category,x.style].join(' ').toLowerCase().includes(q)),pages=Math.max(1,Math.ceil(items.length/12));relatedPage=Math.min(relatedPage,pages);$('#related-choices').innerHTML=items.slice((relatedPage-1)*12,relatedPage*12).map(x=>'<label class="check"><input type="checkbox" data-related value="'+esc(x.id)+'" '+(p.related.includes(x.id)?'checked':'')+'>'+esc(x.title)+'</label>').join('')||'<p>검색 결과가 없습니다.</p>';$('#related-selected').innerHTML=p.related.map(id=>{const item=pool().find(x=>x.id===id);return item?'<button type="button" data-related-remove="'+esc(id)+'">'+esc(item.title)+' ×</button>':'';}).join('');$('#related-pagination').innerHTML=pages>1?Array.from({length:pages},(_,i)=>'<button type="button" data-related-page="'+(i+1)+'" aria-current="'+(relatedPage===i+1?'page':'false')+'">'+(i+1)+'</button>').join(''):'';}
 $('#related-search').addEventListener('input',()=>{relatedPage=1;renderRelated();});$('#related-pagination').addEventListener('click',e=>{const b=e.target.closest('[data-related-page]');if(b){relatedPage=Number(b.dataset.relatedPage);renderRelated();}});$('#related-selected').addEventListener('click',e=>{const b=e.target.closest('[data-related-remove]');if(b){syncDocument();p.related=p.related.filter(x=>x!==b.dataset.relatedRemove);renderRelated();paint();changed();}});
 $('#style-suggestions').addEventListener('click',e=>{const b=e.target.closest('[data-style-pick]');if(b){syncDocument();$('#post-style').value=b.dataset.stylePick;readSettings();paint();changed();}});
 function installHeroDrag(){if(current.status==='archived')return;for(const [selector,kind] of [['.cms-cover','photo'],['.cms-heading','title']]){const el=$('#document-canvas '+selector),handle=document.createElement('button');handle.type='button';handle.className='hero-grip';handle.draggable=false;handle.dataset.dragHero=kind;handle.textContent='⠿ '+(kind==='photo'?'대표 사진':'제목')+' 배치';el.prepend(handle);}}
 const canvas=$('#document-canvas');canvas.addEventListener('dragstart',e=>{const block=e.target.closest('[data-drag-block]'),hero=e.target.closest('[data-drag-hero]');if(busy||(!block&&!hero)){e.preventDefault();return;}syncDocument();dragged=block?{index:Number(block.dataset.dragBlock)}:{hero:hero.dataset.dragHero};e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',block?'nemo-block':'nemo-hero');canvas.classList.add('is-dragging');});
 canvas.addEventListener('dragover',e=>{if(!dragged)return;const target=e.target.closest('[data-block-index],[data-hero-drop]');if(target){e.preventDefault();e.dataTransfer.dropEffect='move';}});canvas.addEventListener('dragend',()=>{dragged=null;canvas.classList.remove('is-dragging');});

 function finishDrag(target,x,y){if(!dragged)return;const hero=target?.closest('[data-hero-drop]'),block=target?.closest('[data-block-index]');if(dragged.hero&&hero){p.heroLayout=hero.dataset.heroDrop;$('#hero-layout').value=p.heroLayout;paint();changed();}else if(block&&dragged.index!==undefined){const from=dragged.index,to=Number(block.dataset.blockIndex);if(from!==to){const rect=block.getBoundingClientRect(),horizontal=(x-rect.left)/rect.width,left=horizontal<.22,right=horizontal>.78,after=right||(!left&&y>rect.top+rect.height/2),destination=p.blocks[to],moved=p.blocks.splice(from,1)[0],at=p.blocks.indexOf(destination)+(after?1:0);if(left||right){moved.layout='half';destination.layout='half';}p.blocks.splice(at,0,moved);active=at;paint();changed();}}dragged=null;canvas.classList.remove('is-dragging');}
 canvas.addEventListener('drop',e=>{if(dragged){e.preventDefault();finishDrag(e.target,e.clientX,e.clientY);}});
 let pointerDrag=null;canvas.addEventListener('pointerdown',e=>{const block=e.target.closest('[data-drag-block]'),hero=e.target.closest('[data-drag-hero]');if(busy||(!block&&!hero)||e.button!==0)return;e.preventDefault();syncDocument();dragged=block?{index:Number(block.dataset.dragBlock)}:{hero:hero.dataset.dragHero};pointerDrag={id:e.pointerId,x:e.clientX,y:e.clientY,handle:e.target};e.target.setPointerCapture(e.pointerId);});canvas.addEventListener('pointermove',e=>{if(pointerDrag&&Math.hypot(e.clientX-pointerDrag.x,e.clientY-pointerDrag.y)>5)canvas.classList.add('is-dragging');});canvas.addEventListener('pointerup',e=>{if(!pointerDrag)return;const moved=Math.hypot(e.clientX-pointerDrag.x,e.clientY-pointerDrag.y)>5,target=document.elementFromPoint(e.clientX,e.clientY);pointerDrag.handle.releasePointerCapture(e.pointerId);pointerDrag=null;if(moved)finishDrag(target,e.clientX,e.clientY);else{dragged=null;canvas.classList.remove('is-dragging');}});canvas.addEventListener('pointercancel',()=>{pointerDrag=null;dragged=null;canvas.classList.remove('is-dragging');});
 canvas.addEventListener('click',e=>{const b=e.target.closest('[data-hero-drop]');if(b){syncDocument();p.heroLayout=b.dataset.heroDrop;$('#hero-layout').value=p.heroLayout;paint();changed();}});


 function renderAuthorChoices(){const value=$('#author-filter').value,authors=[...new Set(posts.filter(x=>x.status!=='archived').map(x=>x.author).filter(Boolean))];$('#author-filter').innerHTML='<option value="all">모든 작성자</option><option value="unknown">기존 글 · 작성자 미상</option>'+authors.map(a=>'<option value="'+esc(a)+'">'+esc(a)+'</option>').join('');$('#author-filter').value=['all','unknown',...authors].includes(value)?value:'all';}
 $('#author-filter').addEventListener('change',()=>renderList(true));$('#admin-sort').addEventListener('change',()=>renderList(true));
 function updateHistoryButtons(){$('#undo-edit').disabled=busy||current?.status==='archived'||historyIndex<=0;$('#redo-edit').disabled=busy||current?.status==='archived'||historyIndex>=history.length-1;}
 function remember(){if(!p||replaying)return;const value=JSON.stringify(p);if(history[historyIndex]===value){updateHistoryButtons();return;}history=history.slice(0,historyIndex+1);history.push(value);if(history.length>100)history.shift();historyIndex=history.length-1;updateHistoryButtons();}
 function restoreFields(){const fields={'post-category':p.category,'post-font':p.font,'hero-layout':p.heroLayout,'post-style':p.style,'post-kind':p.kind,'post-points':(p.points||[]).join(', '),'price-mode':p.price?.mode||'none','price-unit':p.price?.unit||'','price-total':p.price?.total||'','related-mode':p.relatedMode};for(const [id,value]of Object.entries(fields))$('#'+id).value=value||'';$('#show-toc').checked=p.showToc!==false;$('#post-actual').checked=!!p.isActual;$('#show-note').checked=p.showNote!==false;renderRelated();$('#related-picker').hidden=p.relatedMode!=='manual';$('#unit-label').hidden=!['unit','both'].includes(p.price?.mode);$('#total-label').hidden=!['total','both'].includes(p.price?.mode);}
 function undoRedo(delta){if(busy||!p)return;const next=historyIndex+delta;if(next<0||next>=history.length)return;replaying=true;historyIndex=next;p=JSON.parse(history[next]);active=Math.min(active,p.blocks.length-1);restoreFields();paint();dirty=true;$('#save-state').textContent='저장되지 않은 변경 사항';replaying=false;updateHistoryButtons();toast(delta<0?'이전 상태로 되돌렸습니다.':'변경을 다시 적용했습니다.');}
 $('#undo-edit').addEventListener('click',()=>undoRedo(-1));$('#redo-edit').addEventListener('click',()=>undoRedo(1));document.addEventListener('keydown',e=>{if(p&&!busy&&(e.ctrlKey||e.metaKey)&&(e.target.closest('#document-canvas')||e.target===document.body)&&(e.key.toLowerCase()==='z'||e.key.toLowerCase()==='y')){e.preventDefault();undoRedo(e.key.toLowerCase()==='y'||e.shiftKey?1:-1);}});
 function showVideo(index=-1){if(busy||!current||current.status==='archived')return;syncDocument();videoEdit=index;$('#video-address').value=index>=0?p.blocks[index].url||'https://www.youtube.com/watch?v='+p.blocks[index].videoId:'';$('#video-error').textContent='';$('#video-dialog').showModal();$('#video-address').focus();}
 const photoSection=$('#image-settings'),photoDetails=photoSection.closest('details');$('#image-dialog').append(photoSection);photoDetails.remove();$('#close-image-settings').addEventListener('click',()=>$('#image-dialog').close());
 $('#video-form').addEventListener('submit',e=>{e.preventDefault();const url=$('#video-address').value.trim(),videoId=R.youtubeId(url);if(!videoId){$('#video-error').textContent='올바른 유튜브 영상 주소를 입력해주세요.';return;}if(videoEdit<0){if(p.blocks.length>=96){$('#video-error').textContent='본문은 최대 96개입니다.';return;}replaying=true;insert('youtube');replaying=false;videoEdit=active;}p.blocks[videoEdit]={...p.blocks[videoEdit],url,videoId};paint();changed();$('#video-dialog').close();});$('#close-video').addEventListener('click',()=>$('#video-dialog').close());

 addEventListener('beforeunload',event=>{if(dirty){event.preventDefault();event.returnValue='';}});
